BEGIN IMMEDIATE;
CREATE TABLE archive_meta(singleton INTEGER PRIMARY KEY CHECK(singleton=1),schema_version INTEGER NOT NULL,account_token TEXT NOT NULL,store_id TEXT NOT NULL,revision TEXT NOT NULL,generation TEXT NOT NULL,maintenance_id TEXT NOT NULL,envelope BLOB NOT NULL);
CREATE TABLE messages(position INTEGER PRIMARY KEY,message_key TEXT UNIQUE NOT NULL,chat_kind INTEGER NOT NULL,chat_token TEXT NOT NULL,message_id INTEGER NOT NULL,deleted INTEGER NOT NULL,purged INTEGER NOT NULL,transcript_date INTEGER NOT NULL,head_version TEXT NOT NULL,causal_order TEXT NOT NULL,envelope BLOB NOT NULL);
CREATE INDEX deleted_transcript ON messages(chat_token,deleted,purged,transcript_date DESC,message_id DESC,message_key DESC);
CREATE INDEX message_purge ON messages(chat_token,message_key);
CREATE TABLE versions(message_key TEXT NOT NULL,version_id TEXT NOT NULL,order_key TEXT NOT NULL,chat_token TEXT NOT NULL,envelope BLOB NOT NULL,PRIMARY KEY(message_key,version_id),FOREIGN KEY(message_key) REFERENCES messages(message_key) ON DELETE CASCADE);
CREATE TABLE body_refs(message_key TEXT NOT NULL,version_id TEXT NOT NULL,blob_id TEXT NOT NULL,bytes INTEGER NOT NULL,chunk_count INTEGER NOT NULL,PRIMARY KEY(message_key,version_id),FOREIGN KEY(message_key,version_id) REFERENCES versions(message_key,version_id) ON DELETE CASCADE);
CREATE TABLE body_chunks(message_key TEXT NOT NULL,version_id TEXT NOT NULL,chunk_index INTEGER NOT NULL,envelope BLOB NOT NULL,PRIMARY KEY(message_key,version_id,chunk_index),FOREIGN KEY(message_key,version_id) REFERENCES body_refs(message_key,version_id) ON DELETE CASCADE);
CREATE INDEX version_cursor ON versions((message_key||'/'||version_id));
CREATE INDEX version_order ON versions(message_key,order_key DESC);
CREATE INDEX version_chat ON versions(chat_token,message_key,version_id);
CREATE TABLE events(position INTEGER PRIMARY KEY,message_key TEXT NOT NULL,event_id TEXT NOT NULL,fingerprint TEXT NOT NULL,envelope BLOB NOT NULL,UNIQUE(message_key,event_id),FOREIGN KEY(message_key) REFERENCES messages(message_key) ON DELETE CASCADE);
CREATE INDEX event_cursor ON events((message_key||'/'||event_id));
CREATE TABLE blobs(position INTEGER PRIMARY KEY,blob_id TEXT UNIQUE NOT NULL,bytes TEXT NOT NULL,state INTEGER NOT NULL,envelope BLOB NOT NULL);
CREATE INDEX blob_state ON blobs(state,blob_id);
CREATE TABLE media_refs(message_key TEXT NOT NULL,version_id TEXT NOT NULL,media_token TEXT NOT NULL,position INTEGER NOT NULL,state INTEGER NOT NULL,blob_id TEXT,PRIMARY KEY(message_key,version_id,media_token),FOREIGN KEY(message_key,version_id) REFERENCES versions(message_key,version_id) ON DELETE CASCADE,FOREIGN KEY(blob_id) REFERENCES blobs(blob_id) DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX blob_references ON media_refs(blob_id);
CREATE INDEX media_copies ON media_refs(media_token,state,blob_id);
CREATE TABLE jobs(position INTEGER PRIMARY KEY,job_id TEXT UNIQUE NOT NULL,message_key TEXT NOT NULL,version_id TEXT NOT NULL,chat_token TEXT NOT NULL,state INTEGER NOT NULL,generation TEXT NOT NULL,chat_generation TEXT NOT NULL,envelope BLOB NOT NULL);
CREATE INDEX pending_jobs ON jobs(chat_token,state,job_id);
CREATE TABLE leases(position INTEGER PRIMARY KEY,lease_id TEXT UNIQUE NOT NULL,blob_id TEXT NOT NULL,chat_token TEXT NOT NULL,revoked INTEGER NOT NULL,envelope BLOB NOT NULL,FOREIGN KEY(blob_id) REFERENCES blobs(blob_id) DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX blob_readers ON leases(blob_id);
CREATE INDEX chat_readers ON leases(chat_token,revoked,lease_id);
CREATE TABLE purge_epochs(position INTEGER PRIMARY KEY,chat_token TEXT UNIQUE NOT NULL,generation TEXT NOT NULL,envelope BLOB NOT NULL);
CREATE TABLE maintenance(singleton INTEGER PRIMARY KEY CHECK(singleton=1),operation_id TEXT NOT NULL,kind INTEGER NOT NULL,scope_token TEXT NOT NULL,phase INTEGER NOT NULL,cursor TEXT NOT NULL,envelope BLOB NOT NULL);
CREATE TABLE capture_gaps(gap_id TEXT PRIMARY KEY,observed_at INTEGER NOT NULL,reason TEXT NOT NULL,fingerprint TEXT NOT NULL,envelope BLOB NOT NULL);
CREATE INDEX gap_order ON capture_gaps(observed_at,gap_id);
INSERT INTO archive_meta VALUES(1,1,'02318b89dfe3847d2e71e3fd3ce0c84cb705b2f9e1b3555ac9048a7538bb61e3','fixture-store','0','0','',X'');
COMMIT;
